x,height=350px');return false">syawn</a></span> [sjawn] <em>n.</em> blessing<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/4900.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syay</a></span> [sjaj] <em>n.</em> fate<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/6380.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syayvi</a></span> [ˈsjaj.vi] <em>n.</em> luck, chance<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/11248.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">sye&#8217;otxang</a></span> [ˈsjɛ.ʔo.t&#8217;aŋ] <em>n.</em> wind instrument<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/8732.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syeha</a></span> [ˈsjɛ.ha] <em>n.</em> breath<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/8736.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syeha si</a></span> [ˈsjɛ.ha s·i] <em>vin.</em> breathe<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/4888.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syen</a></span> [sjɛn] <em>adj.</em> last, final (in a sequence)<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/3860.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syep</a></span> [sj·ɛp̚] <em>vtr.</em> trap<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/13438.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syep&#8217;an</a></span> [ˈsjɛp̚.ʔan] <em>n.</em> lift vine, trap vine<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/9184.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syeprel</a></span> [sjɛp̚.ˈɾɛl] <em>n.</em> camera<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/5724.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syeptute</a></span> [ˈsjɛp̚.tu.tɛ] <em>n.</em> hyneman, person trapper<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/10944.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syewe</a></span> [ˈsjɛ.wɛ] <em>n.</em> fat (substance in meat)<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/10948.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syewenga&#8217;</a></span> [ˈsjɛ.wɛ.ŋaʔ] <em>adj.</em> fatty<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/13365.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syìmawnun&#8217;i</a></span> [sjɪ.maw.nʊn.ˈʔi] <em>n.</em> cut tie, dissolved connection<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/5460.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syo</a></span> [sjo] <em>adj.</em> light (physical weight), lightweight<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/10888.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syokup</a></span> [sjo.ˈkʊp̚] <em>n.</em> weight (physical)<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/9232.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syon</a></span> [sjon] <em>n.</em> feature, trait, attribute, characteristic, point, aspect, facet, property<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/11308.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syonlì&#8217;u</a></span> [ˈsjon.lɪ.ʔu] <em>n.</em> adjective<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/9556.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syor</a></span> [sj·oɾ] <em>vin.</em> relax, chill out<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/1948.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syulang</a></span> [ˈsju.laŋ] <em>n.</em> flower<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/8612.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syura</a></span> [sju.ˈɾa] <em>n.</em> energy (physical or spiritual)<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/8616.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syuratan</a></span> [sju.ˈɾa.tan] <em>n.</em> bioluminescence<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/10616.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syusmung</a></span> [ˈsju.smʊŋ] <em>n.</em> food tray<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/4620.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syuve</a></span> [ˈsju.vɛ] <em>n.</em> food (collective noun, cannot be pluralized)<br /><span style="font-weight: bold; margin-left: -0.7em;"><a class="map_excluded" href="https://s.learnnavi.org/audio/vocab/10452.mp3" onclick="window.open(this.href,this.target,'width=550px,height=350px');return false">syuvekel</a></span> [ˈsju.vɛ.kɛl] <em>n.</em> famine</div>
